// FS-I18N-016: localized UI strings. en is the source of truth; id mirrors it.
// Keys are stable identifiers; values are [en, id] pairs. Parameterization uses
// {name} placeholders; EN pluralization uses {count} + {s} (id drops {s}).
export type Locale = 'en' | 'id'

export const SUPPORTED_LOCALES: Locale[] = ['en', 'id']
export const DEFAULT_LOCALE: Locale = 'en'

export function normalizeLocale(value: string | null | undefined): Locale {
  const normalized = (value ?? '').trim().toLowerCase()
  return (SUPPORTED_LOCALES as string[]).includes(normalized) ? (normalized as Locale) : DEFAULT_LOCALE
}

