export function translate(key: string, locale: string | null | undefined, params?: Record<string, string | number>): string {
  const normalized = normalizeLocale(locale)
  const entry = CATALOG[key]
  let text = entry ? entry[normalized === 'id' ? 1 : 0] : key
  if (params) {
    for (const [name, value] of Object.entries(params)) text = text.replaceAll(`{${name}}`, String(value))
  }
  return text
}
